Merge Sort is a divide-and-conquer algorithm that recursively splits an array into two halves, sorts each half, and then merges them. A variation of this is 3-way Merge Sort, where instead of splitting the array into two parts, we divide it into three equal parts. In traditional Merge Sort, the array is recursively divided into halves until we reach subarrays of size 1. In 3-way Merge Sort, the array is recursively divided into three parts, reducing the depth of recursion and potentially improving efficiency.Examples:  Input: arr = [45, -2, -45, 78, 30, -42, 10, 19, 73, 93] Output: [-45, -42, -2, 10, 19, 30, 45, 73, 78, 93]Input: arr = [23, -19]Output: [-19, 23]Approach:The idea is to extend merge sort by dividing the array into three parts instead of two. First, recursively sort the three subarrays. Then, merge them by selecting the smallest element among the three at each step. Temporary arrays store the divided parts, and a comparison process finds the minimum to insert into the original array. Steps to implement the above idea:Divide the array into three equal parts using two midpoints.Recursively sort each of the three subarrays.Create temporary arrays to store the three divided parts.Use three pointers to track positions in the three subarrays.Find the minimum element among the three at each step.Merge the sorted subarrays back into the original array.Repeat the process until the entire array is sorted.
            C++

    // C++ program to implement 3-way Merge Sort
#include <bits/stdc++.h>
using namespace std;

void merge(int arr[], int left, int mid1, int mid2, int right) {

    // Sizes of three subarrays
    int size1 = mid1 - left + 1;
    int size2 = mid2 - mid1;
    int size3 = right - mid2;

    // Temporary arrays for three parts
    vector<int> leftArr(size1), midArr(size2), rightArr(size3);

    // Copy data to temporary arrays
    for (int i = 0; i < size1; i++) {
        leftArr[i] = arr[left + i];
    }
    for (int i = 0; i < size2; i++) {
        midArr[i] = arr[mid1 + 1 + i];
    }
    for (int i = 0; i < size3; i++) {
        rightArr[i] = arr[mid2 + 1 + i];
    }

    // Merge three sorted subarrays
    int i = 0, j = 0, k = 0, index = left;
    while (i < size1 || j < size2 || k < size3) {
        int minValue = INT_MAX, minIdx = -1;

        // Find the smallest among the three current elements
        if (i < size1 && leftArr[i] < minValue) {
            minValue = leftArr[i];
            minIdx = 0;
        }
        if (j < size2 && midArr[j] < minValue) {
            minValue = midArr[j];
            minIdx = 1;
        }
        if (k < size3 && rightArr[k] < minValue) {
            minValue = rightArr[k];
            minIdx = 2;
        }

        // Place the smallest element in the merged array
        if (minIdx == 0) {
            arr[index++] = leftArr[i++];
        } else if (minIdx == 1) {
            arr[index++] = midArr[j++];
        } else {
            arr[index++] = rightArr[k++];
        }
    }
}

void threeWayMergeSort(int arr[], int left, int right) {

    // Base case: If single element, return
    if (left >= right) {
        return;
    }

    // Finding two midpoints for 3-way split
    int mid1 = left + (right - left) / 3;
    int mid2 = left + 2 * (right - left) / 3;

    // Recursively sort first third
    threeWayMergeSort(arr, left, mid1);

    // Recursively sort second third
    threeWayMergeSort(arr, mid1 + 1, mid2);

    // Recursively sort last third
    threeWayMergeSort(arr, mid2 + 1, right);

    // Merge the sorted parts
    merge(arr, left, mid1, mid2, right);
}

int main() {

    // Input array
    int arr[] = {5, 2, 9, 1, 6, 3, 8, 4, 7};

    // Size of the array
    int n = sizeof(arr) / sizeof(arr[0]);

    // Calling 3-way merge sort function
    threeWayMergeSort(arr, 0, n - 1);

    // Printing the sorted array
    for (int i = 0; i < n; i++) {
        cout << arr[i] << " ";
    }

    return 0;
}


